-- BOA-630: 予測を一度も走らせていない1,476レース（2026-09-21 の結果のバックフィルで補ったレース）の races の導出列のうち、
-- race_entries から決まる6列（first_boat_grade・first_boat_win_rate・first_boat_motor_2rate・win_rate_avg・
-- win_rate_stddev・motor_2rate_stddev）を埋める。モデルの出力（volatility_*・recommended_model・first_boat_avg_st）は
-- 埋めない（NULL のまま。今のモデルで計算しても当時の判定ではない）。予測（predictions）は作らない。
--
-- 生成: node --env-file=.env.local scripts/maintenance/build-races-derived-backfill-sql.js --out=<このファイル>（2026-10-02）
--   値は generate-predictions.js と同じ式で計算した。予測のある588レース（2026-05-15・07-03・08-20・09-10）で、
--   保存済みの値と6列とも一致することを確かめた（列の桁に丸めて比較）。
--
-- ■ 実行の順（Supabase Dashboard > SQL Editor）
--   1. 事前確認（読み取りのみ）を実行し、期待値と合うことを確かめる
--   2. BEGIN〜COMMIT の本体を実行する → 「UPDATE 1476」
--   3. 事後確認（読み取りのみ）を実行する
--   races に UPDATE のトリガーは無い（docs/db-migration に定義なし。事前確認の(0)で実物も確かめる）。
--   書き込みは races の1,476行の UPDATE だけで、Disk IO への影響は小さい。開催中に実行してもよい
--
-- ■ 事前確認（期待値）
--   (0) SELECT tgname FROM pg_trigger WHERE tgrelid = 'public.races'::regclass AND NOT tgisinternal;
--       → 0行（あれば実行せず連絡する）
--   (1) SELECT substr(r.race_id,1,7) AS m, count(*) FROM races r
--        WHERE r.race_id >= '2026-04-01' AND r.race_id < '2026-10-01' AND r.first_boat_grade IS NULL
--          AND EXISTS (SELECT 1 FROM race_results x WHERE x.race_id = r.race_id)
--          AND NOT EXISTS (SELECT 1 FROM predictions p WHERE p.race_id = r.race_id)
--        GROUP BY 1 ORDER BY 1;
--       → 2026-04: 60 / 05: 276 / 06: 384 / 07: 336 / 08: 132 / 09: 288（計1,476）
--
-- ■ 事後確認（期待値）
--   (2) (1) と同じ SELECT → 0行
--   (3) SELECT substr(race_id,1,7) AS m, count(*) FILTER (WHERE first_boat_grade IS NULL) AS grade_null,
--              count(*) FILTER (WHERE volatility_score IS NULL) AS vol_null
--        FROM races WHERE race_id >= '2026-04-01' AND race_id < '2026-10-01' GROUP BY 1 ORDER BY 1;
--       → grade_null は各月0（9月は当日分の未予測を除く）、vol_null は (1) の件数のまま（モデルの出力は埋めない）
--
-- ■ 取り消し（埋めた6列を NULL に戻す。他の列・表には影響しない）
